import subprocess, re, collections
GD="/home/axel/LeanAlgebraicGeometry-Horizon/.archon-horizon/vcs/workspace.git"
WT="/home/axel/LeanAlgebraicGeometry-Horizon"
base="MainProjects/Algebraic-Jacobian-Challenge-Rebuild/"
def git(*a):
    return subprocess.run(["git","--git-dir",GD,"--work-tree",WT,*a],capture_output=True,text=True).stdout
files=[f for f in git("ls-tree","-r","--name-only","HEAD",base+"AlgebraicJacobian/").splitlines() if f.endswith(".lean")]
print("files under AlgebraicJacobian/:",len(files))
def mod(f):
    return "AlgebraicJacobian."+f[len(base+"AlgebraicJacobian/"):-5].replace("/",".")
imports={}
for f in files:
    body=git("show","HEAD:"+f)
    imports[mod(f)]=set(re.findall(r'^import\s+([A-Za-z0-9_.]+)',body,re.M))
root=git("show","HEAD:"+base+"AlgebraicJacobian.lean")
rootimps=set(re.findall(r'^import\s+([A-Za-z0-9_.]+)',root,re.M))
seen=set(); stack=[m for m in rootimps if m in imports]
while stack:
    m=stack.pop()
    if m in seen: continue
    seen.add(m)
    for d in imports.get(m,()):
        if d in imports and d not in seen: stack.append(d)
unreach=sorted(set(imports)-seen)
print("reachable:",len(seen),"UNREACHABLE:",len(unreach))
for u in unreach: print("   ",u)
EOF
